int dsh_spike_bundle_tree_file(size_t index, const char **path,
                               const char **data, size_t *len) {
  if (index >= 172) return 0;
  if (path) *path = DSH_TREE_PATHS[index];
  if (data) *data = (const char *)DSH_TREE_DATA[index];
  if (len) *len = DSH_TREE_LENS[index];
  return 1;
}

